// MedPrepAide service worker (build 20261118h). Generated by make_site.py from build/sw_template.js.
// - The page (index.html): network first, saved copy when offline.
// - Versioned files (?v=...): one saved copy per file path, replaced when a newer version is fetched;
//   when offline the saved copy is used even if it is an older version. Question subjects are saved
//   only when the learner opens them ("cache as opened").
// - Other files of the app (images, icons, vendor): saved on first use.
// - Fonts and Wikimedia images: saved on first use.
const VER = '20261118h';
const FILES = 'mpa-files', PAGES = 'mpa-pages', EXT = 'mpa-ext';
const SHELL = ['app.js', 'style.css', 'tailwind.css', 'data/index.js', 'data/topics.js'].map(p => p + '?v=' + VER)
  .concat(['vendor/lucide.min.js', 'manifest.webmanifest', 'icon-192.png', 'icon-512.png']);
const EXT_HOSTS = /^(fonts\.googleapis\.com|fonts\.gstatic\.com|commons\.wikimedia\.org|upload\.wikimedia\.org)$/;

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    try { const r = await fetch('./', { cache: 'reload' }); if (r.ok) await (await caches.open(PAGES)).put('./', r); } catch (x) {}
    await Promise.all(SHELL.map(u => {
      const req = new Request(u, { cache: 'reload' });
      return new URL(req.url).searchParams.has('v') ? versioned(req).catch(() => {}) : cacheFirst(req, FILES).catch(() => {});
    }));
    await self.skipWaiting();
  })());
});
self.addEventListener('activate', e => e.waitUntil(self.clients.claim()));

function bare(url) { const u = new URL(url); const v = u.searchParams.get('v'); u.search = ''; return { key: u.href, v }; }
async function versioned(req) {
  const { key, v } = bare(req.url);
  const c = await caches.open(FILES);
  const hit = await c.match(key);
  if (hit && hit.headers.get('x-mpa-v') === v) return hit;
  try {
    const r = await fetch(req);
    if (r.ok) {
      const body = await r.blob();
      const h = new Headers(r.headers); h.set('x-mpa-v', v);
      await c.put(key, new Response(body, { status: 200, headers: h }));
      return new Response(body, { status: 200, headers: h });
    }
    return hit || r;
  } catch (x) {
    if (hit) return hit;
    throw x;
  }
}
async function cacheFirst(req, name) {
  const c = await caches.open(name);
  const hit = await c.match(req, { ignoreVary: true });
  if (hit) return hit;
  const r = await fetch(req);
  if (r.ok || r.type === 'opaque') { try { await c.put(req, r.clone()); } catch (x) {} }
  return r;
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === self.location.origin) {
    if (url.pathname.endsWith('/sw.js')) return;
    if (req.mode === 'navigate') {
      e.respondWith(fetch(req).then(r => {
        if (r.ok) { const copy = r.clone(); caches.open(PAGES).then(c => c.put('./', copy)); }
        return r;
      }).catch(async () => (await (await caches.open(PAGES)).match('./')) || Response.error()));
      return;
    }
    if (url.searchParams.has('v')) { e.respondWith(versioned(req)); return; }
    e.respondWith(cacheFirst(req, FILES));
    return;
  }
  if (EXT_HOSTS.test(url.hostname)) e.respondWith(cacheFirst(req, EXT).catch(() => Response.error()));
});
